import os
import re
import json

RLM_DIR = os.environ.get('RLM_SESSION_DIR', '')
with open(RLM_DIR + '/../../sessions/' + os.path.basename(RLM_DIR) + '.jsonl', 'r') as f:
    t = f.read()

# Parse the JSONL line by line
grids = {}

for line in t.split('\n'):
    if not line.strip():
        continue

    try:
        data = json.loads(line)
    except:
        continue

    # Look for user messages that contain grids
    if 'message' in data and 'role' in data['message']:
        if data['message'].get('role') == 'user':
            for content in data['message'].get('content', []):
                if content.get('type') == 'text':
                    text = content.get('text', '')

                    # Find Test input blocks
                    for match in re.finditer(r'Test input \((\d+)x(\d+)\):\n', text):
                        key = f"Test_{match.start()}"
                        h = int(match.group(1))
                        start = match.end()

                        # Read h lines of grid data
                        pos = text.find('\n', start - 1 + 1)  # Find start of actual content
                        lines = []
                        current = start
                        for i in range(h):
                            nl = text.find('\n', current)
                            if nl == -1:
                                break
                            lines.append(text[current:nl])
                            current = nl + 1

                        if len(lines) == h and all(len(lines[j].strip().split()) == match.group(2) for j in range(h)):
                            grid = [[int(x) for x in line.strip().split()] for line in lines]
                            grids[key] = grid
                            print(f"Found {key}: {h}x{len(grid[0])}")
                            if key == "Test_14364":
                                print(grid)

print(f"\nTotal grids: {len(grids)}")

