        if '8 8 1 1' in line:
            match = re.search(r'"text":"((?:[^"\\]|\\.)*)"', line)
            if match:
                raw_text = match.group(1)
                # Unescape - handle the special sequences
                unescaped = raw_text.replace('\\n', '\n')

                # Find grid data between Test input and Wrong attempts
                start = unescaped.find("8 8 1 1 1 1 1 1 8")
                end = unescaped.find("Wrong attempts")
                if start != -1 and end != -1:
                    grid_lines = unescaped[start:end]
                    grid = [[int(x) for x in line.strip().split()] for line in grid_lines.strip().split('\n') if line.strip()]
                    test_inputs['task-6605c840'] = grid

print(f"Test input grids found: {len(test_inputs)}")
